// The HTTP headers, routes and environment variables every generated
// deployable shares — one spelling for every backend, frontend and the
// compose / Kubernetes / README renderers.
//
// Generated code carries no tool name (docs/decisions/D-NO-TOOL-NAME.md), and
// a name that crosses a deployable boundary (a header a frontend sends, an
// environment variable compose sets and a backend reads) must be spelled the
// same on both sides, so a stack generated by one compiler version agrees with
// itself.  Every emitter reads the names from here;
// `test/system/runtime-wire-name-census.test.ts` refuses a spelled-out copy
// anywhere else in `src/`.

/** HTTP headers (lower-case, as HTTP/2 carries them). */
export const RUNTIME_HEADERS = {
  /** The shared secret the test-reset route requires. */
  testResetToken: "x-test-reset-token",
  /** The dev-stub principal a caller asserts while `DEV_AUTH=1`. */
  devClaims: "x-dev-claims",
  /** The RabbitMQ retry counter a consumer stamps on a re-published message.
   *  RabbitMQ's own `x-delivery-count` (quorum queues) is a different counter. */
  deliveryAttempts: "x-delivery-attempts",
  /** The by-id cache's hit / miss report (`hit`, `miss`). Not `x-cache`,
   *  which CDNs and Varnish overwrite. */
  cacheStatus: "x-cache-status",
} as const;

/** HTTP routes the runtime mounts beside the model's own. */
export const RUNTIME_ROUTES = {
  /** The test-reset hook: under `/__test/`, outside every api prefix. */
  testReset: "/__test/reset",
} as const;

/** Environment variables a generated deployable reads. */
export const RUNTIME_ENV = {
  /** `1` mounts the test-reset route (with the token below). */
  testReset: "TEST_RESET",
  /** The shared secret the test-reset route compares the header against. */
  testResetToken: "TEST_RESET_TOKEN",
  /** Secure cookies and HSTS; on unless set to a false value. */
  secureTransport: "SECURE_TRANSPORT",
  /** Serves the OpenAPI UI. */
  openapiUi: "OPENAPI_UI",
  /** `1` turns on the dev-stub verifier (every request is a built-in identity). */
  devAuth: "DEV_AUTH",
  /** Names the seed datasets applied at first boot. */
  seed: "SEED_DATA",
  /** The database the generated Java integration tests run against — not
   *  `DATABASE_URL`, which the apps read as their runtime database. */
  testDatabaseUrl: "TEST_DATABASE_URL",
  /** Days a dispatched outbox row is kept before the purge deletes it. */
  outboxRetentionDays: "OUTBOX_RETENTION_DAYS",
} as const;

/** The environment variable carrying one channel's broker URL:
 *  `CHANNEL_<NAME>_URL`, the name upper-snaked.  The `_URL` suffix keeps a
 *  channel called `MaxAttempts` apart from `CHANNEL_MAX_ATTEMPTS`. */
export function channelUrlEnv(upperSnakeName: string): string {
  return `CHANNEL_${upperSnakeName}_URL`;
}

/** A header as a snake-case identifier (FastAPI derives the header from a
 *  parameter of this name). */
export function headerParamName(header: string): string {
  return header.replaceAll("-", "_");
}
